HERE=Path(__file__).resolve().parent; TEST=HERE/'test'; DEV=HERE/'development'; METHODS=['K0','K1','K2','K3','K4','K5','v1','everythingTracker']
def write_json(p,v): p.write_text(json.dumps(v,indent=2)+'\n')
def point(items,method):
 y=np.asarray([x['label'] for x in items]); d=np.asarray([x['decisions'][method] for x in items]); s=np.asarray([x['scores'][method] for x in items])
 return {'balancedAccuracy':float(balanced_accuracy_score(y,d)),'precision':float(precision_score(y,d,zero_division=0)),'recall':float(recall_score(y,d,zero_division=0)),'f1':float(f1_score(y,d,zero_division=0)),'prAuc':float(average_precision_score(y,s)),'confusion':{'tn':int(np.sum((y==0)&(~d))),'fp':int(np.sum((y==0)&d)),'fn':int(np.sum((y==1)&(~d))),'tp':int(np.sum((y==1)&d))}}
def view(items,seed,clusters=None):
 groups=[[i] for i in range(len(items))] if clusters is None else list(clusters.values()); rng=np.random.default_rng(seed); samples={m:defaultdict(list) for m in METHODS}; diffs={x:[] for x in ['K0','K1']}; agree=[]; attempts=0
 while len(agree)<1000 and attempts<10000:
  attempts+=1; chosen=np.concatenate([np.asarray(groups[i]) for i in rng.integers(0,len(groups),len(groups))]); sub=[items[i] for i in chosen]
