for i,x in enumerate(pred): clusters[x['siteId']].append(i)
views={'N-B':view(nb,2026111107),'N-A':view(pred,2026111108,clusters)}; diffs=views['N-B']['selectedDifferences']; win=all(x['value']>0 and x['ci95'][0]>0 for x in diffs.values())
fixed=Counter(); missed=Counter()
for x in pred:
 if x['decisions']['K3']==bool(x['label']) and (x['decisions']['K0']!=bool(x['label']) or x['decisions']['K1']!=bool(x['label'])): fixed[x['normalizedName']]+=1
