result={'schemaVersion':1,'selected':'K3','views':views,'agreement':{'N-B':agreement(nb),'N-A':agreement(pred)},'winRule':{'passed':win,'wording':'combination beat both parts' if win else 'the combination did not beat both parts on this test'},'fixedNames':top(fixed),'stillWrongNames':top(missed),'specialNames':special}
